export interface WorkerClientOptions {
  onProgress?: (phase: string, percent?: number) => void;
  onStructuredProgress?: (progress: AnalysisProgress) => void;
  timeout?: number; // ms, default 60s
}

interface PendingTask {
  resolve: (value: WorkerSuccessResponse) => void;
  reject: (reason: Error) => void;
  onProgress?: (phase: string, percent?: number) => void;
  onStructuredProgress?: (progress: AnalysisProgress) => void;
  timer?: ReturnType<typeof setTimeout>;
}

class WorkerDispatchError extends Error {
  constructor(cause: unknown) {
    super(cause instanceof Error ? cause.message : 'Worker message could not be sent');
    this.name = 'WorkerDispatchError';
  }
}

let worker: Worker | null = null;
let taskCounter = 0;
const pendingTasks = new Map<string, PendingTask>();

/**
 * 获取或创建共享 Worker 实例
 * CRA 5 webpack 5 支持 new Worker(new URL(..., import.meta.url))
 */
function getWorker(): Worker {
  if (!worker) {
    worker = new Worker(new URL('./analysisWorker.ts', import.meta.url));
    worker.addEventListener('message', handleWorkerMessage);
    worker.addEventListener('error', handleWorkerError);
  }
  return worker;
}

function handleWorkerMessage(event: MessageEvent<WorkerResponse>) {
  const msg = event.data;
  const task = pendingTasks.get(msg.id);
  if (!task) return;

  switch (msg.type) {
    case 'progress':
      task.onProgress?.(msg.phase, msg.percent);
      if (msg.progress) task.onStructuredProgress?.(msg.progress);
      break;
    case 'success':
      if (task.timer) clearTimeout(task.timer);
      pendingTasks.delete(msg.id);
      task.resolve(msg);
      break;
    case 'error':
      if (task.timer) clearTimeout(task.timer);
      pendingTasks.delete(msg.id);
      task.reject(new Error(msg.error));
      break;
  }
}

function handleWorkerError(event: ErrorEvent) {
  // Worker 级别的未捕获错误：拒绝所有待处理任务
  const error = new Error(`Worker error: ${event.message}`);
  for (const [id, task] of pendingTasks) {
    if (task.timer) clearTimeout(task.timer);
    task.reject(error);
    pendingTasks.delete(id);
  }
  // 重建 Worker
  terminateWorker();
}

function sendToWorker(
  request: WorkerRequest,
  options: WorkerClientOptions = {},
  transfer: Transferable[] = [],
): Promise<WorkerSuccessResponse> {
  return new Promise((resolve, reject) => {
    const w = getWorker();
    const timeout = options.timeout ?? 60_000;

    const timer = setTimeout(() => {
      pendingTasks.delete(request.id);
      reject(new Error(`Worker timeout after ${timeout}ms`));
    }, timeout);

    pendingTasks.set(request.id, {
      resolve,
      reject,
      onProgress: options.onProgress,
      onStructuredProgress: options.onStructuredProgress,
      timer,
    });

    try {
      w.postMessage(request, transfer);
    } catch (error) {
      clearTimeout(timer);
      pendingTasks.delete(request.id);
      reject(new WorkerDispatchError(error));
    }
  });
}

function streamTransfer(
  payload: unknown,
): Transferable[] {
  return isFileStreamParseSession(payload)
    ? [payload.stream as unknown as Transferable]
    : [];
}

async function sendToWorkerWithStreamFallback(
  request: WorkerRequest,
  fallbackRequest: WorkerRequest,
  input: File | FileStreamParseSession,
  options: WorkerClientOptions,
): Promise<WorkerSuccessResponse> {
  if (!isFileStreamParseSession(input)) {
    return sendToWorker(request, options);
  }
  try {
    return await sendToWorker(request, options, streamTransfer(input));
  } catch (error) {
    if (!(error instanceof WorkerDispatchError)) throw error;
    if (!input.stream.locked) {
      await input.stream.cancel(error).catch(() => undefined);
    }
    return sendToWorker(fallbackRequest, options);
  }
}

function nextId(): string {
  return `task-${++taskCounter}-${Date.now()}`;
}

// ============ Public API ============

export interface NetlogParseResult {
  events: ParsedEvent[];
  result: AnalysisResult;
  rawData?: unknown;
  rawDataId?: string;
  datasetMeta?: NetlogDatasetImportResult;
  duration: number;
}

export function largeNetlogTimeout(fileSize: number): number {
  const mb = fileSize / (1024 * 1024);
  const minutes = Math.min(12, 2 + Math.ceil(mb / 100));
  return minutes * 60_000;
}

function isLargeNetlogDebugEnabled(): boolean {
  try {
    return typeof window !== 'undefined' && window.localStorage?.getItem('netlog_large_debug') === '1';
  } catch {
    return false;
  }
}

export interface HarParseResult {
  result: HarAnalysisResult;
  rawData?: unknown;
  rawDataId?: string;
  duration: number;
}

export interface LogParseResult {
  result: LogAnalysisResult;
  duration: number;
}

export interface RawValuePreview {
  text: string;
  truncated: boolean;
}

/**
 * 在 Worker 中搜索原始 JSON path（供 RawEvidenceExplorer 使用）
 */
export async function searchRawJsonInWorker(
  rawDataId: string,
  query: string,
  options?: WorkerClientOptions & { maxResults?: number; maxDepth?: number }
): Promise<JsonPathMatch[]> {
  const id = nextId();
  const response = await sendToWorker(
    {
      type: 'search-raw-json',
      id,
      payload: {
        rawDataId,
        query,
        maxResults: options?.maxResults ?? RAW_EVIDENCE_SEARCH_MAX_RESULTS,
        maxDepth: options?.maxDepth ?? RAW_EVIDENCE_SEARCH_MAX_DEPTH,
      },
    },
    options
  );

  return response.payload as JsonPathMatch[];
}

/**
 * 释放 Worker 内缓存的 rawData（避免长期占用内存）
 */
export async function releaseRawDataInWorker(
  payload: { rawDataId?: string; all?: boolean },
  options?: WorkerClientOptions
): Promise<boolean> {
  const id = nextId();
  const response = await sendToWorker(
    {
      type: 'release-raw-data',
      id,
      payload,
    },
    options
  );
  if (typeof response.payload === 'boolean') {
    return response.payload;
  }
  return Boolean((response.payload as RawReleaseResult).released);
}

